// Collect base company IDs (one item with an id array, or one item per company) and build the filters
const config = $('Configuration').first().json;
const split = value => String(value || '').split(',').map(s => s.trim()).filter(Boolean);
const ids = [...new Set($input.all().flatMap(item => [].concat(item.json.id || [])))];

if (ids.length === 0) {
  throw new Error('No base company IDs found (expected field: id)');
}

const filters = { activeOnly: true };
if (split(config.locations).length) filters.locations = split(config.locations);
if (split(config.industries).length) filters.industries = split(config.industries);
if (split(config.sizes).length) filters.sizes = split(config.sizes);

console.log('Base companies: ' + ids.length + (ids.length > 100 ? ' (only the first 100 are used as seeds for lookalikes)' : ''));

return [{ json: { ids: ids, filters: filters } }];

// Add website, street and description from the profile; keep the company if the profile could not be loaded
const company = $('get_companies').item.json;
const profile = $json.error ? null : $json;
const address = (profile && profile.address) || {};
const contact = (profile && profile.contact) || {};

return {
  json: {
    ...company,
    url: contact.url || '',
    street: address.street || '',
    summary: (profile && profile.summary && profile.summary.value) || '',
    profileLoaded: !!profile
  }
};

// Log failed API calls (after retries)
return $input.all().map(item => {
  const error = item.json.error || {};
  const message = error.message || String(item.json.error || 'Unknown error');
  const status = error.httpCode || (String(message).match(/\b([1-5]\d\d)\b/) || [])[1] || null;
  console.error('API failed: ' + message);
  return {
    json: {
      error_type: 'api_failed',
      error_message: message,
      status_code: status ? Number(status) : null
    }
  };
});

// Pick the base companies whose website-based description feeds the ICP report
const ids = $('collect_ids').first().json.ids;
const sampleSize = $('Configuration').first().json.icp_profile_sample;

return ids.slice(0, sampleSize).map(id => ({ json: { id: id } }));

// Build the text input for the ICP report from the set profile and the company descriptions
const agg = $('get_icp_aggregate').first().json;
const facets = agg.aggregations || {};
const list = (entries, format) => (entries || []).map(format).join('\n');

const years = [];
(facets.foundingYears || []).forEach(y => {
  for (let i = 0; i < y.count; i++) years.push(y.year);
});

const profiles = $input.all()
  .map(item => item.json)
  .filter(p => !p.error && p.summary && p.summary.value);

const parts = [
  'Basisfirmen: ' + agg.matched + ' von ' + agg.requested + ' erkannt',
  '',
  'Branchen (WZ 2008, sortiert nach Überrepräsentation gegenüber allen deutschen Firmen):',
  list(facets.industries, i => '- ' + i.code + ' ' + i.title + ': ' + i.count + ' Firmen' +
    (i.lift ? ', ' + i.lift.toFixed(1) + '-fach überrepräsentiert' : ''))
];

if (agg.focus) {
  parts.push('', 'Branchenfokus: ' + agg.focus.distinctIndustries + ' Branchen, Anteil der drei größten: ' +
    Math.round(agg.focus.topThreeShare * 100) + ' %');
}

parts.push(
  '', 'Größenklassen:', list(facets.sizes, s => '- ' + s.label + ': ' + s.count),
  '', 'Rechtsformen:', list(facets.legalForms, l => '- ' + l.label + ': ' + l.count),
  '', 'Bundesländer:', list(facets.federalStates, s => '- ' + s.label + ': ' + s.count)
);

if (years.length) {
  parts.push('', 'Gründungsjahre: ' + years[0] + ' bis ' + years[years.length - 1] +
    ', Median ' + years[Math.floor(years.length / 2)]);
}

parts.push('', 'Firmenbeschreibungen (' + profiles.length + ' Basisfirmen, aus den Websites abgeleitet):',
  list(profiles, p => '- ' + p.name + ': ' + p.summary.value));

console.log('ICP digest: ' + (facets.industries || []).length + ' industries, ' + profiles.length + ' descriptions');

return [{ json: { text: parts.join('\n') } }];
